window.__PACK__=window.__PACK__||{};window.__PACK__["b_1792499587012"]={"rev":"1tq3qyv","lessons":[{"id":"l_1792499816788","title":"1","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🔬 درس اول: زنگ علوم</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">دانشمندان برای کشف پدیده‌های اطراف خود، ابتدا مشاهده می‌کنند، سپس پرسش‌هایی در ذهنشان ایجاد می‌شود. آنها برای یافتن پاسخ، پیش‌بینی (فرضیه) می‌کنند و با انجام آزمایش (کاوشگری) به نتیجه می‌رسند.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">مراحل کاوشگری</h3>\n<div style=\"background:rgba(16,185,129,0.1); border-right:4px solid #10b981; padding:15px; border-radius:10px; margin:15px 0; line-height:2;\">\n    <strong>۱. مشاهده:</strong> توجه به پدیده‌ها (مثل دیرتر رسیدن بعضی فرفره‌ها به زمین).<br>\n    <strong>۲. پرسش:</strong> چرا این اتفاق می‌افتد؟<br>\n    <strong>۳. پیش‌بینی (فرضیه):</strong> پاسخ حدسی و scientific به پرسش.<br>\n    <strong>۴. آزمایش:</strong> بررسی درستی پیش‌بینی با تغییر دادن یک چیز و اندازه‌گیری چیز دیگر.<br>\n    <strong>۵. نتیجه‌گیری:</strong> ثبت مشاهدات و رسیدن به جواب.\n</div>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">متغیرها در آزمایش</h3>\n<ul style=\"color:#cbd5e1; line-height:2; padding-right:20px;\">\n    <li><strong>چه چیزی را تغییر دادیم؟</strong> (متغیر مستقل) مثلاً پهنای بال فرفره.</li>\n    <li><strong>چه چیزی را اندازه گرفتیم؟</strong> (متغیر وابسته) مثلاً زمان رسیدن فرفره به زمین.</li>\n    <li><strong>چه چیزهایی را تغییر ندادیم؟</strong> (متغیرهای کنترل شده) مثلاً طول بال، جرم، ارتفاع رها کردن.</li>\n</ul>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی زنگ علوم</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">روش علمی</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>مشاهده</strong>دیدن پدیده‌ها</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>پرسش</strong>ایجاد سوال</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>فرضیه</strong>پیش‌بینی پاسخ</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>آزمایش</strong>تغییر یک عامل</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>نتیجه‌گیری</strong>ثبت مشاهدات</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس اول</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: شرایط آزمایش</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">در هر آزمایش برای اینکه نتیجه دقیق باشد، فقط باید <strong>یک چیز</strong> را تغییر دهیم و بقیه شرایط را یکسان نگه داریم.</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: تکرار آزمایش</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">دانشمندان برای اطمینان از درستی نتایج، آزمایش را چندین بار تکرار می‌کنند.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس اول</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. کدام‌یک از مراحل زیر در روش علمی، قبل از «آزمایش» قرار می‌گیرد؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) نتیجه‌گیری &nbsp;&nbsp; <strong>ب) پیش‌بینی (فرضیه)</strong> &nbsp;&nbsp; ج) ثبت مشاهدات</div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. در آزمایش «فرفره چرخان»، اگر پهنای بال را تغییر دهیم، چه چیزی را باید اندازه بگیریم؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) طول بال &nbsp;&nbsp; <strong>ب) زمان رسیدن به زمین</strong> &nbsp;&nbsp; ج) جنس کاغذ</div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ب)، ۲ (ب)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس اول</h2>\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">پاسخ جدول صفحه ۱۲ (نتیجه کاوش فرفره)</h3>\n<p style=\"color:#cbd5e1;\">فرفره‌ای که بال پهن‌تری دارد، <strong>دیرتر</strong> به سطح زمین می‌رسد؛ بنابراین، هر چه <strong>پهنای</strong> بال فرفره <strong>بیشتر</strong> باشد، زمان رسیدن آن به سطح زمین <strong>بیشتر</strong> می‌شود.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">پاسخ جدول صفحه ۱۳ (عوامل موثر بر زمان فرود)</h3>\n<ul style=\"color:#cbd5e1; line-height:2;\">\n    <li><strong>چه چیزی را باید تغییر داد؟</strong> طول بال فرفره</li>\n    <li><strong>چه چیزی را باید اندازه گرفت؟</strong> زمان رسیدن فرفره به زمین</li>\n    <li><strong>چه چیزهایی را نباید تغییر داد؟</strong> پهنای بال، جرم و جنس کاغذ، ارتفاع رها کردن</li>\n</ul>","r":"1lljkvx"},{"id":"l_1792499818925","title":"2","fullHtml":"<!-- TAB: محتوا -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 درس دوم: ماده تغییر می‌کند</h2>\n<p style=\"color:#cbd5e1; line-height:1.9;\">ما در زندگی روزانه برای برطرف کردن نیازهایمان، مواد اطراف خود را تغییر می‌دهیم. این تغییرها به دو دسته کلی تقسیم می‌شوند: تغییرات فیزیکی و تغییرات شیمیایی.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">تغییرات فیزیکی</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">در این تغییرها، شکل و اندازه‌ی ماده تغییر می‌کند؛ ولی <strong>جنس ماده تغییری نمی‌کند</strong> و ماده جدیدی به وجود نمی‌آید. مانند: تا کردن لباس، تکه کردن نان، حل شدن شکر در چای، بریدن کاغذ.</p>\n\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">تغییرات شیمیایی</h3>\n<p style=\"color:#cbd5e1; line-height:1.9;\">در این تغییرها، ماده اولیه به <strong>ماده جدیدی</strong> تبدیل می‌شود. در بیشتر این تغییرها رنگ، بو و مزه ماده تغییر می‌کند. مانند: سوختن قند، پختن نان، فاسد شدن میوه، ترش شدن شیر، زنگ زدن آهن.</p>\n\n<!-- TAB: نمودار درختی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🌳 نمودار درختی تغییرات ماده</h2>\n<div class=\"xmind-container\">\n    <div class=\"xmind-root\">تغییرات ماده</div>\n    <div class=\"xmind-branches\">\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>فیزیکی</strong>تغییر شکل و اندازه (ماده جدید نمی‌شود)</div></div>\n        <div class=\"xmind-branch\"><div class=\"xmind-node\"><strong>شیمیایی</strong>تولید ماده جدید (تغییر رنگ، بو، مزه)</div></div>\n    </div>\n</div>\n\n<!-- TAB: نکات امتحانی -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">📝 نکات امتحانی درس دوم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۱: تفاوت تغییر فیزیکی و شیمیایی</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">اگر بعد از تغییر، ماده جدیدی تولید شود، تغییر شیمیایی است. اگر فقط ظاهر عوض شود، فیزیکی است.</p>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:16px 20px; margin-bottom:14px;\">\n    <h4 style=\"color:#fbbf24; margin-bottom:8px; font-size:1rem;\">⚠️ نکته ۲: سرعت تغییرات</h4>\n    <p style=\"font-size:0.9rem; color:#cbd5e1; line-height:1.8; margin:0;\">برخی تغییرات شیمیایی سریع (مثل سوختن کبریت) و برخی کند (مثل زنگ زدن آهن) هستند.</p>\n</div>\n\n<!-- TAB: آزمون -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">🧪 آزمون درس دوم</h2>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۱. کدام‌یک از موارد زیر یک تغییر شیمیایی است؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) خرد کردن چوب &nbsp;&nbsp; ب) ذوب شدن یخ &nbsp;&nbsp; <strong>ج) پختن تخم‌مرغ</strong> &nbsp;&nbsp; د) بافتن شال گردن</div>\n</div>\n<div style=\"background:rgba(255,255,255,0.04); border:1px solid rgba(255,255,255,0.08); border-radius:14px; padding:20px; margin-bottom:18px;\">\n    <h4 style=\"color:#e2e8f0; margin-bottom:14px;\">۲. در کدام تغییر، ماده اولیه به ماده جدید تبدیل نمی‌شود؟</h4>\n    <div style=\"color:#cbd5e1; line-height:2;\">الف) فاسد شدن میوه &nbsp;&nbsp; <strong>ب) تکه کردن نان</strong> &nbsp;&nbsp; ج) سوختن کاغذ</div>\n</div>\n<div style=\"background:rgba(251,191,36,0.15); border-right:4px solid #fbbf24; padding:15px; border-radius:10px; color:#fde68a;\">\n    💡 <strong>پاسخ‌نامه:</strong> ۱ (ج)، ۲ (ب)\n</div>\n\n<!-- TAB: گام به گام -->\n<h2 style=\"color:#34d399; margin-bottom:15px;\">✍️ گام به گام درس دوم</h2>\n<h3 style=\"color:#6ee7b7; margin-top:20px;\">پاسخ جدول صفحه ۲۰ (تغییرهای محیط اطراف)</h3>\n<table style=\"width:100%; border-collapse:collapse; margin:15px 0; background:rgba(255,255,255,0.05); border-radius:10px; overflow:hidden; text-align:center;\">\n    <tr style=\"background:rgba(5,150,105,0.3); color:#fff;\">\n        <th style=\"padding:10px;\">نام ماده</th>\n        <th style=\"padding:10px;\">کاری که انجام شده است</th>\n        <th style=\"padding:10px;\">نوع تغییر</th>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#cbd5e1;\">کاغذ</td>\n        <td style=\"padding:10px; color:#cbd5e1;\">بریدن</td>\n        <td style=\"padding:10px; color:#fde68a;\">فیزیکی</td>\n    </tr>\n    <tr style=\"border-bottom:1px solid rgba(255,255,255,0.1);\">\n        <td style=\"padding:10px; color:#cbd5e1;\">چوب و نُخ</td>\n        <td style=\"padding:10px; color:#cbd5e1;\">بریدن</td>\n        <td style=\"padding:10px; color:#fde68a;\">فیزیکی</td>\n    </tr>\n    <tr>\n        <td style=\"padding:10px; color:#cbd5e1;\">نخ</td>\n        <td style=\"padding:10px; color:#cbd5e1;\">بستن و گره زدن</td>\n        <td style=\"padding:10px; color:#fde68a;\">فیزیکی</td>\n    </tr>\n</table>","r":"4fgmmf"},{"id":"l_1792499821108","title":"3","enc":{"iv":"W1YX/4QbpwuPMwJ1","ct":""},"r":"9a9p5b"},{"id":"l_1792499823085","title":"4","enc":{"iv":"6qfeGpLRR6deTpsN","ct":""},"r":"1nr9hqh"},{"id":"l_1792499825237","title":"5","enc":{"iv":"TShjlTYSSkEDSE5k","ct":""},"r":"x0w5ct"},{"id":"l_1792499827446","title":"6","enc":{"iv":"bfG+GqGCEnk6iG/d","ct":""},"r":"a4n0g4"},{"id":"l_1792499829260","title":"7","enc":{"iv":"Qc5hfmAgtdJ+EVnH","ct":""},"r":"1kypuh0"},{"id":"l_1792499831260","title":"8","enc":{"iv":"gDNeUBBkX7i5dPNC","ct":""},"r":"i9way8"},{"id":"l_1792499833277","title":"9","enc":{"iv":"jnZyLrAlflgCNXjO","ct":""},"r":"cx1suu"},{"id":"l_1792499835621","title":"درس دهم","enc":{"iv":"QltlCAC+Pmrb4h/B","ct":""},"r":"1sajqkd"},{"id":"l_1792499837637","title":"11","enc":{"iv":"cFv0UmX1lg7gPxJh","ct":""},"r":"rsu2qf"},{"id":"l_1792499839559","title":"12","enc":{"iv":"UGeSfBSGfoMsL+AZ","ct":""},"r":"hpfsh6"}]};